$company=$settings['company_name']??'MADAPT ULDs';$logo=$settings['logo_path']??'';$aircraft=$settings['aircraft_path']??'';$role=strtoupper((string)($u['role']??'OPERATOR'));$isAdmin=$role==='ADMIN';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars($company)?> — MADAPT ULDs</title><link rel="stylesheet" href="assets/app.css"><style>:root{--primary:<?=htmlspecialchars($settings['primary']??'#087a46')?>;--accent:<?=htmlspecialchars($settings['accent']??'#1b8b5b')?>;--sidebar:<?=htmlspecialchars($settings['sidebar']??'#006b3c')?>}.profile-btn{border:0;background:#fff;display:flex;align-items:center;gap:10px;border-radius:28px;padding:6px 14px;cursor:pointer}.profile-btn img{width:34px;height:34px;border-radius:50%;object-fit:cover}.upload-row{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.upload-row input[type=file]{flex:1;min-width:240px}.media-preview{display:flex;gap:18px;align-items:center;margin-top:12px}.media-preview img{max-height:80px;max-width:180px;object-fit:contain;border-radius:8px}.profile-box{max-width:620px}.profile-photo{width:110px;height:110px;border-radius:50%;object-fit:cover;border:4px solid #e8f1ed}.profile-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.portal-logo-form{margin-top:12px}.portal-logo-form input[type=file]{max-width:220px}
.ui-tools{display:flex;align-items:center;gap:6px;position:relative}.ui-tool{border:1px solid #d4e1dc!important;background:#fff!important;color:var(--text)!important;padding:8px 10px!important;border-radius:9px!important;font-weight:700!important;min-width:42px}.lang-menu{display:none;position:absolute;right:50px;top:44px;background:#fff;border:1px solid #dce7e3;border-radius:10px;box-shadow:0 8px 24px rgba(0,0,0,.14);padding:5px;z-index:500;min-width:130px}.lang-menu.open{display:block}.lang-menu button{display:block;width:100%;border:0;background:transparent!important;text-align:left;color:var(--text)!important;padding:9px 10px!important}.lang-menu button:hover{background:#eef6f2!important}.header-actions{display:flex;align-items:center;gap:12px}.mobile-tools{margin-left:auto}.dark-mode{--bg:#101614;--text:#e6f1ed;--muted:#9bb0a8}.dark-mode body{background:var(--bg);color:var(--text)}.dark-mode aside{background:linear-gradient(180deg,#073f29,#03271a)}.dark-mode main,.dark-mode section{background:var(--bg)}.dark-mode header,.dark-mode .madapt-mobilebar,.dark-mode .box,.dark-mode .uld-card,.dark-mode .portal-card,.dark-mode .madapt-footer{background:#17211e!important;color:var(--text);border-color:#2a3a34}.dark-mode h1,.dark-mode h2,.dark-mode h3,.dark-mode header p,.dark-mode .muted,.dark-mode td,.dark-mode th{color:var(--text)}.dark-mode input,.dark-mode select,.dark-mode textarea,.dark-mode .ui-tool,.dark-mode .profile-btn{background:#101815!important;color:var(--text)!important;border-color:#344740!important}.dark-mode table td,.dark-mode table th{border-color:#2b3b35}.dark-mode .lang-menu{background:#17211e;border-color:#344740}.dark-mode .lang-menu button{color:var(--text)!important}.dark-mode .lang-menu button:hover{background:#22332c!important}.dark-mode .uld-card.low{background:#241719}.dark-mode .uld-card.warning{background:#252116}.dark-mode .uld-card.ok{background:#17211e}.dark-mode .good-alert{background:#183025}.dark-mode .danger-alert{background:#351b1e}.dark-mode .status-line.ok{background:#183025}.dark-mode .status-line.warning{background:#332b18}.dark-mode .status-line.low{background:#351b1e}
</style></head><body><div id="app"><aside id="sidebar"><div class="brand"><?php if($logo):?><img src="<?=htmlspecialchars($logo)?>" alt="Logo"><?php else:?><div class="brand-text">Ethiopian<br><small>AIRLINES</small></div><?php endif;?><strong>MADAPT ULDs</strong></div><nav><button data-page="dash">⌂ <span>Dashboard</span></button><button data-page="move">↔ <span>In / Out</span></button><button data-page="inv">▣ <span>Inventory</span></button><button data-page="hist">◷ <span>History</span></button><button data-page="report">▥ <span>Reports</span></button><button data-page="portals">🌐 <span>Portals</span></button><?php if($isAdmin):?><button data-page="users">♙ <span>Users</span></button><button data-page="set">⚙ <span>Settings</span></button><?php endif;?><button data-page="profile">◉ <span>My Profile</span></button><button id="logoutBtn">⇥ <span>Logout</span></button></nav></aside><main><div class="madapt-mobilebar"><button id="menuBtn" aria-label="Menu">☰</button><strong>MADAPT ULDs</strong><div class="ui-tools mobile-tools"><button id="langBtnMobile" class="ui-tool" type="button">🇪🇸 ES ▾</button><button id="themeBtnMobile" class="ui-tool" type="button">🌙</button></div></div><header><div><h1>MADAPT ULDs</h1><p data-i18n="Inventory Management System">Inventory Management System</p></div><div class="header-actions"><div class="ui-tools"><button id="langBtn" class="ui-tool" type="button">🇪🇸 ES ▾</button><div id="langMenu" class="lang-menu"><button type="button" data-lang="es">🇪🇸 Español</button><button type="button" data-lang="en">🇬🇧 English</button></div><button id="themeBtn" class="ui-tool" type="button">🌙</button></div><button class="profile-btn" onclick="show('profile')"><?php if(!empty($u['profile_photo'])):?><img src="<?=htmlspecialchars($u['profile_photo'])?>" alt="Profile"><?php endif;?><?=htmlspecialchars($u['full_name']??$u['username']??'')?></button></div></header><section id="content"><div class="box"><b>Loading...</b></div></section></main></div><script>
const IS_ADMIN=<?=$isAdmin?'true':'false'?>,USER_ROLE=<?=json_encode($role)?>,COMPANY=<?=json_encode($company)?>,LOGO=<?=json_encode($logo)?>,AIRCRAFT=<?=json_encode($aircraft)?>,CURRENT_USER=<?=json_encode($u,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)?>;const ULD_TYPES=['AKE','PAJ','PMC','PAG'];let stock=[],hist=[],flights=[],recipients=[],portalList=[];
const I18N={en:{'Dashboard':'Dashboard','In / Out':'In / Out','Inventory':'Inventory','History':'History','Reports':'Reports','Portals':'Portals','Users':'Users','Settings':'Settings','My Profile':'My Profile','Logout':'Logout','Inventory Management System':'Inventory Management System','Current Stock Overview':'Current Stock Overview','Recent Activity':'Recent Activity','Stock Status':'Stock Status','All ULD stock levels are above the minimum.':'All ULD stock levels are above the minimum.','LOW STOCK ALERT':'LOW STOCK ALERT','NEAR MINIMUM':'NEAR MINIMUM','LOW STOCK':'LOW STOCK','OK':'OK','Minimum':'Minimum','In / Out — Stock Movement':'In / Out — Stock Movement','Quantity':'Quantity','Reference / Remarks':'Reference / Remarks','Additional remarks':'Additional remarks','Submit Movement':'Submit Movement','Flight Number':'Flight Number','Current':'Current','Status':'Status','Time':'Time','Type':'Type','ULD':'ULD','Qty':'Qty','Flight':'Flight','User':'User','Stock Summary':'Stock Summary','Print Stock Summary':'Print Stock Summary','Profile photo':'Profile photo','Every approved user can upload or replace their own photo.':'Every approved user can upload or replace their own photo.','Upload Photo':'Upload Photo','Company & Appearance':'Company & Appearance','Company name':'Company name','Save Settings':'Save Settings','Upload Logo':'Upload Logo','Upload Aircraft Image':'Upload Aircraft Image','Low Stock Email Alert':'Low Stock Email Alert','Enable Low Stock Alerts':'Enable Low Stock Alerts','Email subject':'Email subject','Save Email Alert':'Save Email Alert','Alert Recipients':'Alert Recipients','Add Recipient':'Add Recipient','Flights':'Flights','Add Flight':'Add Flight','Portal Administration':'Portal Administration','Portal name':'Portal name','Description':'Description','Open Portal ↗':'Open Portal ↗','Add Portal':'Add Portal','Edit':'Edit','Delete':'Delete','Upload Portal Logo':'Upload Portal Logo','Could not load data':'Could not load data','Loading...':'Loading...','Menu':'Menu'},es:{'Dashboard':'Panel','In / Out':'Entradas / Salidas','Inventory':'Inventario','History':'Historial','Reports':'Informes','Portals':'Portales','Users':'Usuarios','Settings':'Configuración','My Profile':'Mi perfil','Logout':'Cerrar sesión','Inventory Management System':'Sistema de gestión de inventario','Current Stock Overview':'Resumen del stock actual','Recent Activity':'Actividad reciente','Stock Status':'Estado del stock','All ULD stock levels are above the minimum.':'Todos los niveles de ULD están por encima del mínimo.','LOW STOCK ALERT':'ALERTA DE STOCK BAJO','NEAR MINIMUM':'CERCA DEL MÍNIMO','LOW STOCK':'STOCK BAJO','OK':'OK','Minimum':'Mínimo','In / Out — Stock Movement':'Entradas / Salidas — Movimiento de stock','Quantity':'Cantidad','Reference / Remarks':'Referencia / Observaciones','Additional remarks':'Observaciones adicionales','Submit Movement':'Registrar movimiento','Flight Number':'Número de vuelo','Current':'Actual','Status':'Estado','Time':'Hora','Type':'Tipo','ULD':'ULD','Qty':'Cantidad','Flight':'Vuelo','User':'Usuario','Stock Summary':'Resumen de stock','Print Stock Summary':'Imprimir resumen de stock','Profile photo':'Foto de perfil','Every approved user can upload or replace their own photo.':'Todos los usuarios aprobados pueden subir o cambiar su foto.','Upload Photo':'Subir foto','Company & Appearance':'Empresa y apariencia','Company name':'Nombre de la empresa','Save Settings':'Guardar configuración','Upload Logo':'Subir logo','Upload Aircraft Image':'Subir imagen del avión','Low Stock Email Alert':'Alerta de email de stock bajo','Enable Low Stock Alerts':'Activar alertas de stock bajo','Email subject':'Asunto del email','Save Email Alert':'Guardar alerta de email','Alert Recipients':'Destinatarios de alertas','Add Recipient':'Añadir destinatario','Flights':'Vuelos','Add Flight':'Añadir vuelo','Portal Administration':'Administración de portales','Portal name':'Nombre del portal','Description':'Descripción','Open Portal ↗':'Abrir portal ↗','Add Portal':'Añadir portal','Edit':'Editar','Delete':'Eliminar','Upload Portal Logo':'Subir logo del portal','Could not load data':'No se pudieron cargar los datos','Loading...':'Cargando...','Menu':'Menú'}};
let currentLang=localStorage.getItem('madapt_lang')||'en',currentTheme=localStorage.getItem('madapt_theme')||'light';function t(s){return(I18N[currentLang]&&I18N[currentLang][s])||s}function translateRoot(root=document){root.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t(el.getAttribute('data-i18n')));root.querySelectorAll('input,textarea,select').forEach(el=>{if(el.placeholder)el.placeholder=t(el.placeholder)});root.querySelectorAll('button,th,h2,h3,p,label,small,span').forEach(el=>{if(el.children.length===0){const v=el.textContent.trim();if(I18N[currentLang]&&I18N[currentLang][v])el.textContent=t(v)}});root.querySelectorAll('option').forEach(el=>{const v=el.textContent.trim();if(I18N[currentLang]&&I18N[currentLang][v])el.textContent=t(v)})}
function applyTheme(){document.documentElement.classList.toggle('dark-mode',currentTheme==='dark');const icon=currentTheme==='dark'?'☀️':'🌙';['themeBtn','themeBtnMobile'].forEach(id=>{const b=document.getElementById(id);if(b)b.textContent=icon})}function setTheme(){currentTheme=currentTheme==='dark'?'light':'dark';localStorage.setItem('madapt_theme',currentTheme);applyTheme()}function setLang(lang){currentLang=lang==='es'?'es':'en';localStorage.setItem('madapt_lang',currentLang);document.documentElement.lang=currentLang;['langBtn','langBtnMobile'].forEach(id=>{const b=document.getElementById(id);if(b)b.textContent=currentLang==='es'?'🇪🇸 ES ▾':'🇬🇧 EN ▾'});document.getElementById('langMenu')?.classList.remove('open');translateRoot(document);if(document.body.dataset.page)show(document.body.dataset.page)}function initUI(){applyTheme();document.documentElement.lang=currentLang;setLang(currentLang);document.getElementById('themeBtn')?.addEventListener('click',setTheme);document.getElementById('themeBtnMobile')?.addEventListener('click',setTheme);document.getElementById('langBtn')?.addEventListener('click',()=>document.getElementById('langMenu')?.classList.toggle('open'));document.getElementById('langBtnMobile')?.addEventListener('click',()=>setLang(currentLang==='es'?'en':'es'));document.querySelectorAll('#langMenu [data-lang]').forEach(b=>b.addEventListener('click',()=>setLang(b.dataset.lang)));document.getElementById('menuBtn')?.addEventListener('click',e=>{e.stopPropagation();document.getElementById('sidebar')?.classList.toggle('open')});document.addEventListener('click',e=>{const sidebar=document.getElementById('sidebar'),menuBtn=document.getElementById('menuBtn');if(window.innerWidth<=700&&sidebar?.classList.contains('open')&&!sidebar.contains(e.target)&&e.target!==menuBtn)sidebar.classList.remove('open')})}
async function A(action,data={},form=false){const opts={method:'POST'};if(form)opts.body=data;else{opts.headers={'Content-Type':'application/json'};opts.body=JSON.stringify(data)}const r=await fetch('api.php?action='+encodeURIComponent(action),opts);let j;try{j=await r.json()}catch(e){throw new Error('Invalid server response (HTTP '+r.status+')')}if(!j.ok)throw new Error(j.error||'Request failed');return j}
function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]) )}function stockState(x){const cur=Number(x.current_stock??0),min=Number(x.minimum_level??10);if(cur<=min)return'low';if(cur<=min+Math.max(3,Math.ceil(min*.25)))return'warning';return'ok'}function stateLabel(s){return s==='low'?'LOW STOCK':s==='warning'?'NEAR MINIMUM':'OK'}function movementType(x){return x.movement_type??x.type??''}function uldType(x){return x.uld_type??x.uld??''}function qty(x){return Number(x.quantity??x.qty??0)}function flight(x){return x.flight_number??x.flight??''}function userName(x){return x.user_name??x.username??''}
async function load(){const[s,h]=await Promise.all([A('stock'),A('history')]);stock=s.stock||[];hist=h.history||h.movements||[];flights=s.flights||[]}
function lowAlert(){const low=stock.filter(x=>stockState(x)==='low');if(!low.length)return'<div class="stock-alert good-alert">✓ All ULD stock levels are above the minimum.</div>';return'<div class="stock-alert danger-alert"><span class="blink-dot"></span><b>LOW STOCK ALERT</b><span>'+low.map(x=>esc(uldType(x))+' — '+Number(x.current_stock)+' / '+Number(x.minimum_level)).join(' &nbsp; • &nbsp; ')+'</span></div>'}
function stockCards(){return'<div class="uld-grid">'+stock.map(x=>{const s=stockState(x),cur=Number(x.current_stock),min=Number(x.minimum_level);return`<div class="uld-card ${s}"><div class="uld-head"><span>${esc(uldType(x))}</span><b>${stateLabel(s)}</b></div><div class="uld-number">${cur}</div><div class="uld-min">Minimum ${min}</div><div class="uld-bar"><i style="width:${Math.min(100,Math.max(0,(cur/Math.max(min*2,1))*100))}%"></i></div></div>`}).join('')+'</div>'}
function historyTable(rows=hist){return`<div class="table-wrap"><table><thead><tr><th>Time</th><th>Type</th><th>ULD</th><th>Qty</th><th>Reference / Remarks</th><th>Flight</th><th>User</th>${IS_ADMIN?'<th>Actions</th>':''}</tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.created_at)}</td><td><span class="movement ${movementType(x)==='IN'?'in':'out'}">${esc(movementType(x))}</span></td><td><b>${esc(uldType(x))}</b></td><td>${movementType(x)==='IN'?'+':'-'}${qty(x)}</td><td>${esc(x.reference)} ${esc(x.remarks)}</td><td>${esc(flight(x))}</td><td>${esc(userName(x))}</td>${IS_ADMIN?`<td><button type="button" onclick="editMovement(${Number(x.id)})">Edit</button> <button type="button" class="danger-btn" onclick="deleteMovement(${Number(x.id)})">Delete</button></td>`:''}</tr>`).join('')}</tbody></table></div>`}
async function movementAdmin(action,id,data={}){const r=await fetch('movement_admin.php?action='+encodeURIComponent(action),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,...data})});let j;try{j=await r.json()}catch(e){throw new Error('Invalid server response (HTTP '+r.status+')')}if(!j.ok)throw new Error(j.error||'Request failed');await load();await show('hist');return j}
async function editMovement(id){if(!IS_ADMIN)return;const x=hist.find(m=>Number(m.id)===Number(id));if(!x){alert('Movement not found');return}const type=prompt('Type (IN/OUT):',movementType(x));if(type===null)return;const uld=prompt('ULD:',uldType(x));if(uld===null)return;const quantity=prompt('Quantity:',qty(x));if(quantity===null)return;const flightNumber=prompt('Flight number:',flight(x));if(flightNumber===null)return;const reference=prompt('Reference:',x.reference||'');if(reference===null)return;const remarks=prompt('Remarks:',x.remarks||'');if(remarks===null)return;try{await movementAdmin('edit',id,{movement_type:type,uld_type:uld,quantity:Number(quantity),flight_number:flightNumber,reference,remarks});alert('Movement updated')}catch(e){alert(e.message)}}
async function deleteMovement(id){if(!IS_ADMIN)return;const x=hist.find(m=>Number(m.id)===Number(id));if(!x)return;if(!confirm('Delete this movement? This will adjust the stock.'))return;try{await movementAdmin('delete',id);alert('Movement deleted')}catch(e){alert(e.message)}}
async function show(page){document.body.dataset.page=page;document.getElementById('sidebar')?.classList.remove('open');const c=document.getElementById('content');c.innerHTML='<div class="box"><b>Loading...</b></div>';try{if(['dash','move','inv','hist','report'].includes(page))await load()}catch(e){c.innerHTML='<div class="box error"><b>Could not load data</b><p>'+esc(e.message)+'</p></div>';return}
if(page==='dash')c.innerHTML=`<h2>Current Stock Overview</h2>${lowAlert()}${stockCards()}<div class="two"><div class="box"><h3>Recent Activity</h3>${historyTable(hist.slice(0,8))}</div><div class="box"><h3>Stock Status</h3>${stock.map(x=>`<p class="status-line ${stockState(x)}"><b>${esc(uldType(x))}</b> — ${Number(x.current_stock)} / minimum ${Number(x.minimum_level)}</p>`).join('')}</div></div>`;
if(page==='move'){c.innerHTML=`<h2>In / Out — Stock Movement</h2><div class="box"><form id="mf"><select name="movement_type"><option>IN</option><option>OUT</option></select><select name="uld_type">${ULD_TYPES.map(x=>'<option>'+x+'</option>').join('')}</select><input name="quantity" type="number" min="1" placeholder="Quantity" required><input name="reference" placeholder="Reference / Remarks"><select name="flight_number"><option value="">Flight Number</option>${flights.map(x=>`<option value="${esc(x.flight_number)}">${esc(x.flight_number)}</option>`).join('')}</select><input name="remarks" placeholder="Additional remarks"><button>Submit Movement</button></form><p id="mm"></p></div>`;document.getElementById('mf').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.quantity=+d.quantity;try{await A('movement',d);show('dash')}catch(x){document.getElementById('mm').textContent=x.message}}}
if(page==='inv')c.innerHTML=`<h2>Inventory</h2>${lowAlert()}<div class="box"><div class="table-wrap"><table><tr><th>ULD</th><th>Current</th><th>Minimum</th><th>Status</th></tr>${stock.map(x=>`<tr><td><b>${esc(uldType(x))}</b></td><td>${x.current_stock}</td><td>${x.minimum_level}</td><td>${stateLabel(stockState(x))}</td></tr>`).join('')}</table></div></div>`;
if(page==='hist')c.innerHTML=`<h2>History</h2><div class="box">${historyTable()}</div>`;
if(page==='report')c.innerHTML=`<h2>Stock Summary</h2><div class="box print-area"><div class="print-header">${LOGO?`<img src="${esc(LOGO)}" alt="Logo">`:''}<div><h2>${esc(COMPANY)}</h2><p>MADAPT ULDs — Stock Summary</p><small>Generated: ${esc(new Date().toLocaleString())}</small></div></div><table><tr><th>ULD</th><th>Current</th><th>Minimum</th><th>Status</th></tr>${stock.map(x=>`<tr><td>${esc(uldType(x))}</td><td>${x.current_stock}</td><td>${x.minimum_level}</td><td>${stateLabel(stockState(x))}</td></tr>`).join('')}</table><button class="print-button" onclick="window.print()">Print Stock Summary</button></div>`;
if(page==='users')await users(c);if(page==='portals')await portals(c);if(page==='set')await settingsPage(c);if(page==='profile')await profilePage(c);translateRoot(c)}
async function profilePage(c){const photo=CURRENT_USER.profile_photo||'';c.innerHTML=`<h2>My Profile</h2><div class="box profile-box"><div class="media-preview"><div>${photo?`<img class="profile-photo" src="${esc(photo)}" alt="Profile photo">`:'<div class="profile-photo" style="display:flex;align-items:center;justify-content:center">◉</div>'}</div><div><h3>${esc(CURRENT_USER.full_name||CURRENT_USER.username)}</h3><p>${esc(CURRENT_USER.email||'')} · ${esc(CURRENT_USER.role||'')}</p></div></div><hr><h3>Profile photo</h3><p class="muted">Every approved user can upload or replace their own photo.</p><form id="pfoto" enctype="multipart/form-data"><div class="upload-row"><input name="profile_photo" type="file" accept="image/jpeg,image/png,image/webp" required><button>Upload Photo</button></div></form><p id="pmsg"></p></div>`;document.getElementById('pfoto').onsubmit=async e=>{e.preventDefault();try{const r=await A('profile_upload',new FormData(e.target),true);CURRENT_USER.profile_photo=r.profile_photo;document.getElementById('pmsg').textContent='Profile photo updated.';show('profile')}catch(x){document.getElementById('pmsg').textContent=x.message}}}
async function settingsPage(c){try{const r=await A('settings_get'),s=r.settings||{};flights=r.flights||[];recipients=r.recipients||[];c.innerHTML=`<h2>Settings</h2><div class="box"><h3>Company & Appearance</h3><form id="sf"><input name="company_name" value="${esc(s.company_name||'MADAPT ULDs')}" placeholder="Company name"><input name="primary" type="color" value="${esc(s.primary||'#087a46')}"><input name="accent" type="color" value="${esc(s.accent||'#1b8b5b')}"><input name="sidebar" type="color" value="${esc(s.sidebar||'#006b3c')}"><input type="hidden" name="logo_path" value="${esc(s.logo_path||'')}"><input type="hidden" name="aircraft_path" value="${esc(s.aircraft_path||'')}"><button>Save Settings</button></form><p id="sm"></p><div class="media-preview">${s.logo_path?`<img src="${esc(s.logo_path)}" alt="Logo">`:''}${s.aircraft_path?`<img src="${esc(s.aircraft_path)}" alt="Aircraft">`:''}</div><hr><h3>Upload Logo</h3><form id="logoForm" enctype="multipart/form-data"><div class="upload-row"><input name="logo" type="file" accept="image/jpeg,image/png,image/webp" required><button>Upload Logo</button></div></form><p id="lm"></p><h3>Upload Aircraft Image</h3><form id="airForm" enctype="multipart/form-data"><div class="upload-row"><input name="aircraft" type="file" accept="image/jpeg,image/png,image/webp" required><button>Upload Aircraft</button></div></form><p id="am"></p></div><div class="box"><h3>Low Stock Email Alert</h3><label class="check"><input id="lsa" type="checkbox" ${s.low_stock_alerts==='1'||s.low_stock_alerts==='true'?'checked':''}> Enable Low Stock Alerts</label><input id="les" value="${esc(s.low_stock_email_subject||'MADAPT ULDs - Low Stock Alert')}" placeholder="Email subject"><textarea id="lem" rows="10">${esc(s.low_stock_email_message||'Dear Team,\n\nThis is an automatic notification from MADAPT ULDs Inventory Management.\n\nULD {ULD_TYPE} has reached or fallen below its minimum stock level.\n\nCurrent stock: {CURRENT_STOCK}\nMinimum level: {MINIMUM_LEVEL}\n\nKind regards,\nMADAPT ULDs Inventory Management')}</textarea><button id="saveMail">Save Email Alert</button></div><div class="box"><h3>Alert Recipients</h3><form id="ef"><div class="upload-row"><input name="email" type="email" placeholder="email@example.com" required><button>Add Recipient</button></div></form><div>${recipients.map(x=>`<p><b>${esc(x.email)}</b> — ${Number(x.active)?'Active':'Disabled'} <button onclick="toggleEmail(${x.id})">Toggle</button> <button class="danger-btn" onclick="deleteEmail(${x.id})">Delete</button></p>`).join('')}</div></div><div class="box"><h3>Flights</h3><form id="ff"><div class="upload-row"><input name="flight_number" placeholder="ET740" required><button>Add Flight</button></div></form><div>${flights.map(x=>`<p><b>${esc(x.flight_number)}</b> — ${Number(x.active)?'Active':'Disabled'} <button onclick="toggleFlight(${x.id})">Toggle</button> <button class="danger-btn" onclick="deleteFlight(${x.id})">Delete</button></p>`).join('')}</div></div>`;document.getElementById('sf').onsubmit=async e=>{e.preventDefault();try{await A('settings_save',Object.fromEntries(new FormData(e.target)));document.getElementById('sm').textContent='Saved successfully.'}catch(x){document.getElementById('sm').textContent=x.message}};document.getElementById('logoForm').onsubmit=async e=>{e.preventDefault();try{await A('asset_upload',new FormData(e.target),true)}catch(x){document.getElementById('lm').textContent=x.message;return}document.getElementById('lm').textContent='Logo uploaded. Reloading…';location.reload()};document.getElementById('airForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);fd.append('kind','aircraft');try{await A('asset_upload',fd,true);document.getElementById('am').textContent='Aircraft image uploaded.';show('set')}catch(x){document.getElementById('am').textContent=x.message}};document.getElementById('logoForm').addEventListener('formdata',e=>e.formData.append('kind','logo'));document.getElementById('saveMail').onclick=async e=>{e.preventDefault();try{await A('settings_email_save',{enabled:document.getElementById('lsa').checked,subject:document.getElementById('les').value,message:document.getElementById('lem').value});alert('Low Stock email settings saved.')}catch(x){alert(x.message)}};document.getElementById('ef').onsubmit=async e=>{e.preventDefault();try{await A('alert_email_add',Object.fromEntries(new FormData(e.target)));show('set')}catch(x){alert(x.message)}};document.getElementById('ff').onsubmit=async e=>{e.preventDefault();try{await A('flight_add',Object.fromEntries(new FormData(e.target)));show('set')}catch(x){alert(x.message)}}}catch(e){c.innerHTML='<div class="box error">'+esc(e.message)+'</div>'}}
async function users(c){try{const r=await A('users');c.innerHTML=`<h2>User Approval</h2><div class="box"><div class="table-wrap"><table><tr><th>User</th><th>Name</th><th>Photo</th><th>Role</th><th>Status</th><th>Action</th></tr>${r.users.map(x=>`<tr><td>${esc(x.username)}</td><td>${esc(x.full_name)}</td><td>${x.profile_photo?`<img src="${esc(x.profile_photo)}" style="width:36px;height:36px;border-radius:50%;object-fit:cover">`:''}</td><td><select onchange="setRole(${x.id},this.value)"><option ${x.role==='OPERATOR'?'selected':''}>OPERATOR</option><option ${x.role==='SUPERVISOR'?'selected':''}>SUPERVISOR</option><option ${x.role==='ADMIN'?'selected':''}>ADMIN</option></select></td><td>${Number(x.active)?'approved':'pending'}</td><td>${Number(x.active)?'':'<button onclick="ap('+x.id+',\'approved\')">Approve</button>'}</td></tr>`).join('')}</table></div></div>`}catch(e){c.innerHTML='<div class="box error">'+esc(e.message)+'</div>'}}
async function portals(c){try{const r=await A('portals');portalList=r.portals||[];c.innerHTML=`<h2>Portals</h2><p class="muted">Access operational portals from one place. Only administrators can add, edit, delete or upload portal logos.</p>${IS_ADMIN?'<div class="box"><h3>Portal Administration</h3><form id="portalForm" enctype="multipart/form-data"><input name="name" placeholder="Portal name" required><input name="url" placeholder="https://..." required><input name="description" placeholder="Description"><div class="upload-row"><input name="logo" type="file" accept="image/jpeg,image/png,image/webp"><button>Add Portal</button></div></form><p id="portalMsg"></p></div>':''}<div class="portal-grid">${portalList.map(x=>`<div class="portal-card"><div class="portal-logo">${x.logo_path?`<img src="${esc(x.logo_path)}" alt="${esc(x.name)}">`:'🌐'}</div><h3>${esc(x.name)}</h3><p>${esc(x.description)}</p><a href="${esc(x.url)}" target="_blank" rel="noopener">Open Portal ↗</a>${IS_ADMIN?`<div class="portal-actions"><button onclick="editPortal(${x.id})">Edit</button> <button class="danger-btn" onclick="deletePortal(${x.id})">Delete</button><form class="portal-logo-form" id="plf-${x.id}" enctype="multipart/form-data"><input name="portal_logo" type="file" accept="image/jpeg,image/png,image/webp" required><button type="submit">Upload Logo</button></form><p id="plm-${x.id}"></p></div>`:''}</div>`).join('')}</div>`;if(IS_ADMIN){document.getElementById('portalForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);const name=String(fd.get('name')||'').trim(),url=String(fd.get('url')||'').trim(),description=String(fd.get('description')||'').trim(),logoFile=fd.get('logo');try{const r=await A('portal_add',{name,url,description});if(logoFile&&logoFile.size){const lf=new FormData();lf.append('portal_id',r.id);lf.append('portal_logo',logoFile);await A('portal_logo_upload',lf,true)}show('portals')}catch(x){document.getElementById('portalMsg').textContent=x.message}};portalList.forEach(x=>{const f=document.getElementById('plf-'+x.id);if(f)f.onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);fd.append('portal_id',String(x.id));try{await A('portal_logo_upload',fd,true);show('portals')}catch(err){document.getElementById('plm-'+x.id).textContent=err.message}}})}}catch(e){c.innerHTML='<div class="box error">'+esc(e.message)+'</div>'}}
async function editPortal(id){if(!IS_ADMIN)return;const x=portalList.find(p=>+p.id===+id);if(!x)return;const name=prompt('Portal name',x.name);if(name===null)return;const url=prompt('Portal URL',x.url);if(url===null)return;const description=prompt('Description',x.description||'');if(description===null)return;try{await A('portal_update',{id,name:name.trim(),url:url.trim(),description:description.trim(),logo_path:x.logo_path||''});show('portals')}catch(e){alert(e.message)}}
async function deletePortal(id){if(!IS_ADMIN)return;if(!confirm('Delete this portal?'))return;try{await A('portal_delete',{id});show('portals')}catch(e){alert(e.message)}}
async function ap(id,status){try{await A('approve',{id,status});show('users')}catch(e){alert(e.message)}}async function setRole(id,role){try{await A('set_role',{id,role})}catch(e){alert(e.message)}}async function deleteEmail(id){if(confirm('Delete recipient?'))try{await A('alert_email_delete',{id});show('set')}catch(e){alert(e.message)}}async function toggleEmail(id){try{await A('alert_email_toggle',{id});show('set')}catch(e){alert(e.message)}}async function deleteFlight(id){if(confirm('Delete flight?'))try{await A('flight_delete',{id});show('set')}catch(e){alert(e.message)}}async function toggleFlight(id){try{await A('flight_toggle',{id});show('set')}catch(e){alert(e.message)}}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>show(b.dataset.page));document.getElementById('logoutBtn').onclick=async()=>{try{await A('logout')}finally{location.href='login.php'}};initUI();show('dash');
</script></body></html>